glsl3.vert:
precision highp float;
uniform CCGlobal {
  vec4 cc_time;

  vec4 cc_screenSize;

  vec4 cc_screenScale;

  vec4 cc_nativeSize;

  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;

  vec4 cc_exposure;

  vec4 cc_mainLitDir;

  vec4 cc_mainLitColor;

  vec4 cc_ambientSky;
  vec4 cc_ambientGround;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};

in vec3 a_position;
in vec4 a_color;
out vec4 v_color;

#if USE_TEXTURE
in vec2 a_uv0;
out vec2 v_uv0;
#endif

void main () {
  vec4 pos = vec4(a_position, 1);

  pos = cc_matViewProj * pos;

  #if USE_TEXTURE
  v_uv0 = a_uv0;
  #endif

  v_color = a_color;

  gl_Position = pos;
}

glsl3.frag:
precision highp float;

#if USE_ALPHA_TEST

  uniform ALPHA_TEST {
    float alphaThreshold;
  }
#endif

void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
      if (color.a < alphaThreshold) discard;
  #endif
}

void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
      if (alpha < alphaThreshold) discard;
  #endif
}

in vec4 v_color;

#if USE_TEXTURE
in vec2 v_uv0;
uniform sampler2D texture;
#endif

uniform PROPERTIES {
  vec4 uvRange;
  float slope;
  float xoffset;
  float rotated;
}

vec2 convertUV(vec2 uv) {
  float x = (uv.x - uvRange[0]) / uvRange[1];
  float y = (uv.y - uvRange[2]) / uvRange[3];
  if (rotated == 1.0) {
    return vec2(y, x);
  } else {
    return vec2(x, y);
  }
}

vec4 filter(vec4 texColor, vec2 uv) {
  if (texColor[3] == 0.0) {
    return texColor;
  }
  float width = 0.2;
  float start = xoffset * (1.0 + width);
  float strength = .7;
  float offset = slope;
  if (rotated == 1.0) {
    offset = -slope;
  }
  float left = start - uv.y * offset - width;
  float right = left + width;
  float midx = max(0.0000001, (left + right) / 2.0);
  if (uv.x < right && uv.x > left) {
    float a = (uv.x - left) / width;
    return vec4(texColor.r, texColor.g, texColor.b, texColor.a * (1.0 - a));
  } else if (uv.x >= right) {
    return vec4(0.0, 0.0, 0.0, 0.0);
  } else {
    return texColor;
  }
}

void main () {
  vec4 texColor = texture2D(texture, v_uv0);
  vec2 uv = convertUV(v_uv0);
  vec4 o = vec4(1, 1, 1, 1);
  o *= v_color * filter(texColor, uv);
  #if CC_USE_ALPHA_ATLAS_TEXTURE
    o.a *= texture2D(texture, v_uv0 + vec2(0, 0.5)).r;
  #endif
  gl_FragColor = o;
}

